  $('#pageCountCsvBtn').onclick=exportPageCountsCsv;$('#exportPdfBtn').onclick=openSubmissionSettings;$('#printPageBtn').onclick=printCurrentPage;$('#fullscreenBtn').onclick=toggleDrawingFullscreen;$('#issueFocusBtn').onclick=toggleIssueFocus;$('#prevPage').onclick=()=>changePage(-1);$('#nextPage').onclick=()=>changePage(1);$('#zoomIn').onclick=()=>setZoom(state.zoom*1.15);$('#zoomOut').onclick=()=>setZoom(state.zoom/1.15);$('#fitBtn').onclick=()=>setZoom(1);$('#csvBtn').onclick=exportCsv;
  $('#reportBtn').onclick=reportSettingsDialog;$('#pageLabel').onclick=()=>editPageLabel(state.pdfPage);$('#cancelPlaceBtn').onclick=clearPlacementMode;$('#continuousPlace').onchange=e=>{state.keepPlacing=e.target.checked;showToast(state.keepPlacing?'連続配置をオンにしました':'1個ずつ配置します')};window.addEventListener('keydown',e=>{if(e.key==='Escape')clearPlacementMode()});
