function printCurrentPage(){if(!state.pdf){showToast('先に図面PDFを読み込んでください');return}const wrap=$('#pageWrap'),rect=wrap.getBoundingClientRect(),fit=Math.min(1,1060/rect.width,730/rect.height);wrap.style.transform=`scale(${fit})`;wrap.style.transformOrigin='center center';const restore=()=>{wrap.style.transform='';wrap.style.transformOrigin='';window.removeEventListener('afterprint',restore)};window.addEventListener('afterprint',restore);window.print()}
