function updatePageLabel(){if(!state.pdf){$('#pageLabel').textContent='図面未選択';return}const label=state.project.pageLabels?.[state.pdfPage];$('#pageLabel').textContent=`${label?`${label}　・　`:''}${state.pdfPage} / ${state.pdf.numPages}`;$('#pageLabel').title=label?'クリックしてページ名を変更':'クリックして階数・図面名を設定';renderPageList()}
function editPageLabel(page=state.pdfPage){if(!state.pdf)return;const old=state.project.pageLabels?.[page]||'';const value=prompt(`ページ${page}の名前（例：1階平面図、屋上階）`,old);if(value===null)return;state.project.pageLabels=state.project.pageLabels||{};if(value.trim())state.project.pageLabels[page]=value.trim();else delete state.project.pageLabels[page];saveSoon();updatePageLabel();renderEquipmentList();renderPageList()}
function countUnit(t){return t.countUnit||(t.category==='smoke'?'箇所':t.category==='other'?'件':'台')}
