function renderCounts(){const all=state.project?.markers||[];const done=all.filter(m=>m.checked).length;$('#markerCount').textContent=`設備 ${all.length}件 ・ 点検済 ${done}/${all.length}`;$('#equipmentCount').textContent=all.length}
function saveBasicSettings(){state.project.types=state.types;if(state.activeType&&!typeWorkMatch(getType(state.activeType)))clearPlacementMode();saveSoon();renderPalette();renderMaster();renderCounts()}
function environmentPackFromProject(project=state.project){const base=state.envSettings||defaultEnvironmentSettings();return {format:'tenken-pwa-settings',schemaVersion:1,name:`${project?.name||'現場点検ノート'} 環境設定`,workCategoryMaster:structuredClone(project?.workCategoryMaster||base.workCategoryMaster),equipmentGroupMaster:structuredClone(project?.equipmentGroupMaster||base.equipmentGroupMaster),types:normalizeTypes(project?.types||base.types),findingCategories:structuredClone(project?.findingCategories||base.findingCategories||[]),wordingSets:structuredClone(project?.wordingSets||base.wordingSets||[]),reportDefaults:structuredClone(project?.reportDefaults||base.reportDefaults||{workContent:''})}}
