function markerPointerDown(e){const el=e.target.closest('.map-marker');if(!el)return;e.preventDefault();const id=el.dataset.id;const startX=e.clientX,startY=e.clientY;const mark=state.project.markers.find(m=>m.id===id);const rect=$('#pageWrap').getBoundingClientRect();const origX=mark.x,origY=mark.y;let moved=false;el.setPointerCapture?.(e.pointerId);const move=ev=>{if(pinchSessionActive)return;if(Math.abs(ev.clientX-startX)+Math.abs(ev.clientY-startY)>5)moved=true;if(!moved)return;mark.x=Math.max(0,Math.min(1,origX+(ev.clientX-startX)/rect.width));mark.y=Math.max(0,Math.min(1,origY+(ev.clientY-startY)/rect.height));el.style.left=`${mark.x*100}%`;el.style.top=`${mark.y*100}%`;el.dataset.dragged='1'};const up=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);if(pinchSessionActive){ignoreGestureClickUntil=Date.now()+700;return}if(moved){saveSoon();setTimeout(()=>{el.dataset.dragged=''},150)}else{state.selectedMarker=id;renderEquipmentList();el.dataset.pointerOpened='1';setTimeout(()=>{el.dataset.pointerOpened=''},500);openMarkerForm(id)}};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true})}
async function onPdfSelected(e){const f=e.target.files?.[0];if(!f)return;await loadPdfBlob(f,true);e.target.value=''}
async function loadPdfBlob(blob,save){try{const task=pdfjsLib.getDocument({data:await blob.arrayBuffer()});state.pdf=await task.promise;state.project.pdfBlob=blob;state.project.pdfName=blob.name||state.project.pdfName||'図面.pdf';state.project.pdfPageCount=state.pdf.numPages;state.pdfPage=1;$('#emptyState').hidden=true;$('#pageWrap').hidden=false;$('#exportPdfBtn').disabled=false;updateProjectFields();await renderPage(1);renderAll();if(save){saveSoon();showToast(`${state.pdf.numPages}ページの図面を読み込みました`)}}catch(err){showToast('PDFを読み込めませんでした');console.error(err)}}
async function renderPage(number){if(!state.pdf)return;state.pdfPage=number;const page=await state.pdf.getPage(number);const area=$('#drawingArea');const viewport0=page.getViewport({scale:1});const available=Math.max(260,area.clientWidth-36);state.baseScale=Math.min(available/viewport0.width,1.25);state.scale=state.baseScale*state.zoom;const vp=page.getViewport({scale:state.scale});const canvas=$('#pdfCanvas');const context=canvas.getContext('2d');const dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.floor(vp.width*dpr);canvas.height=Math.floor(vp.height*dpr);canvas.style.width=`${vp.width}px`;canvas.style.height=`${vp.height}px`;$('#pageWrap').style.width=`${vp.width}px`;$('#pageWrap').style.height=`${vp.height}px`;$('#markerLayer').style.width=`${vp.width}px`;$('#markerLayer').style.height=`${vp.height}px`;await page.render({canvasContext:context,viewport:vp,transform:dpr!==1?[dpr,0,0,dpr,0,0]:null}).promise;updatePageLabel();$('#prevPage').disabled=number<=1;$('#nextPage').disabled=number>=state.pdf.numPages;$('#zoomLabel').textContent=`${Math.round(state.zoom*100)}%`;renderMarkers()}
