function buildMarkerForm(m,t){const place=`<section class="modal-panel" data-modal-panel="place" hidden><div class="form-grid"><div class="field"><span>整理記号</span><input id="fMark" value="${escapeHtml(m.mark||t.mark||'')}" placeholder="例：FD"></div><div class="field"><span>整理番号</span><input id="fSerial" value="${escapeHtml(m.serial||'')}" placeholder="例：1-1"></div><div class="field full-span"><span>設備種別</span><select id="fType">${state.types.map(x=>`<option value="${escapeHtml(x.id)}" ${x.id===m.typeId?'selected':''}>${escapeHtml(x.name)}</option>`).join('')}</select></div><div class="field full-span"><span>設置位置メモ</span><input id="fMemo" value="${escapeHtml(m.memo||'')}" placeholder="例：廊下側から見て小扉が右"></div><label class="checked-control full-span"><input id="fCountIncluded" type="checkbox" ${(m.countIncluded??(t.countByDefault!==false))?'checked':''}>台数集計に含める</label><div class="field"><span>整理番号の表示位置</span><select id="fLabelPosition"><option value="bottom" ${(m.labelPosition||t.labelPosition||'bottom')==='bottom'?'selected':''}>下</option><option value="left" ${(m.labelPosition||t.labelPosition)==='left'?'selected':''}>左</option><option value="right" ${(m.labelPosition||t.labelPosition)==='right'?'selected':''}>右</option><option value="top" ${(m.labelPosition||t.labelPosition)==='top'?'selected':''}>上</option></select></div><div class="field full-span"><span>図面上の大きさ（微調整・12～90px）</span><input id="fSize" type="range" min="12" max="90" value="${m.size||t.defaultSize||22}"></div><div class="field"><span>回転（度）</span><div class="rotation-control"><input id="fRotation" type="number" min="0" max="359" step="45" value="${m.rotation||0}"><button id="rotMinus" class="icon-btn" type="button">−45</button><button id="rotPlus" class="icon-btn" type="button">＋45</button></div></div><div class="field"><span>反転</span><div><label><input id="fFlipX" type="checkbox" ${m.flipX?'checked':''}> 左右</label>　<label><input id="fFlipY" type="checkbox" ${m.flipY?'checked':''}> 上下</label></div></div></div></section>`;const measurements=t.form==='door'?doorForm(m):t.form==='smokeOutlet'?smokeForm(m):t.form==='smokeWindow'?'<div class="form-section">排煙窓の測定・確認</div><p class="master-intro">測定メモや指摘内容は「指摘・写真」タブに記録できます。</p>':'<div class="form-section">測定欄はありません</div><p class="master-intro">写真やメモは「指摘・写真」タブから登録できます。</p>';return `<nav class="modal-tabs"><button type="button" data-modal-tab="measure" class="active">測定</button><button type="button" data-modal-tab="findings">指摘・写真</button><button type="button" data-modal-tab="place">配置</button></nav><section class="modal-panel" data-modal-panel="measure"><label class="checked-control"><input id="fChecked" type="checkbox" ${m.checked?'checked':''}> 点検済み</label>${measurements}${extraFieldsHtml(m,t)}</section><section class="modal-panel" data-modal-panel="findings" hidden><div class="form-section">指摘・特記事項・参考写真 <button id="addFinding" type="button" class="text-btn">＋追加</button></div><div id="findingList">${(m.findings||[]).map((f,i)=>findingHtml(f,i,m)).join('')}</div></section>${place}<div class="modal-hint">変更は「保存」を押すと、この案件に反映されます。</div>`}
function doorForm(m){return `<div class="form-section">扉ごとの測定</div>${(m.components||[]).map((c,i)=>`<div class="leaf-card" data-leaf="${i}"><div class="leaf-title"><strong>${escapeHtml(c.label)}</strong><small>番号と左右の基準は設置位置メモにも記録できます</small></div><div class="form-grid"><div class="field"><span>高さ（m）</span><input data-comp="height" type="number" step="0.001" value="${escapeHtml(c.height)}"></div><div class="field"><span>幅（m）</span><input data-comp="width" type="number" step="0.001" value="${escapeHtml(c.width)}"></div><div class="field"><span>閉鎖時間（秒）</span><input data-comp="time" type="number" step="0.01" value="${escapeHtml(c.time)}"></div><div class="field"><span>閉鎖力（N）</span><input data-comp="force" type="number" step="0.1" value="${escapeHtml(c.force)}"></div><div class="field full-span"><span>危害防止装置</span><select data-comp="hazard"><option value="" ${!c.hazard?'selected':''}>未入力</option><option ${c.hazard==='良'?'selected':''}>良</option><option ${c.hazard==='否'?'selected':''}>否</option><option ${c.hazard==='未設置'?'selected':''}>未設置</option><option ${c.hazard==='対象外'?'selected':''}>対象外</option></select></div></div></div>`).join('')}`}
function smokeForm(m){const vals=m.velocities||['','','','',''];const avg=average(vals);return `<div class="form-section">排煙口の測定</div><div class="form-grid"><div class="field"><span>縦（m）</span><input id="fHeight" type="number" step="0.001" value="${escapeHtml(m.height||'')}"></div><div class="field"><span>横（m）</span><input id="fWidth" type="number" step="0.001" value="${escapeHtml(m.width||'')}"></div><div class="field"><span>開口面積（m²）</span><div id="areaCalc" class="calc-value">${calcArea(m.height,m.width)}</div></div><div class="field"><span>風速平均（m/s）</span><div id="velocityAvg" class="calc-value">${avg===null?'5点入力で計算':avg.toFixed(2)}</div></div><div class="field full-span"><span>5点の風速測定値（m/s）</span><div class="velocity-grid">${vals.map((v,i)=>`<input data-velocity="${i}" aria-label="風速${i+1}" type="number" step="0.01" value="${escapeHtml(v)}" placeholder="${i+1}点目">`).join('')}</div></div></div>`}
