function showModal(title,html,onSave,onDelete,deleteText='設備を削除',onDuplicate=null){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-header"><div><h2>${title}</h2><p>点検記録</p></div><button class="close-btn" id="modalClose">×</button></div><div class="modal-body">${html}</div><div class="modal-footer"><div><button class="btn btn-danger" id="modalDelete" ${onDelete?'':'hidden'}>${deleteText}</button><button class="btn btn-light" id="modalDuplicate" ${onDuplicate?'':'hidden'}>複写して配置</button></div><div><button class="btn btn-light" id="modalCancel">閉じる</button><button class="btn btn-primary" id="modalSave">保存</button></div></div></div></div>`;$('#modalClose').onclick=()=>closeModal();$('#modalCancel').onclick=()=>closeModal();$('#modalSave').onclick=onSave;$('#modalDelete').onclick=onDelete;$('#modalDuplicate').onclick=onDuplicate;$('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()})}
