async function compressImage(file,maxEdge){try{const bmp=await createImageBitmap(file);const ratio=Math.min(1,maxEdge/Math.max(bmp.width,bmp.height));const c=document.createElement('canvas');c.width=Math.round(bmp.width*ratio);c.height=Math.round(bmp.height*ratio);c.getContext('2d').drawImage(bmp,0,0,c.width,c.height);bmp.close?.();return await new Promise(resolve=>c.toBlob(resolve,'image/jpeg',.86))}catch(e){return file}}
