function exportPageCountsCsv(){const pages=state.pdf?.numPages||Math.max(0,...(state.project?.markers||[]).map(m=>Number(m.page)||0));if(!pages){showToast('ページ情報がありません');return}const rows=[['ページ','ページ名','設備名','整理記号','数量','単位']];for(let page=1;page<=pages;page++)for(const {type,count} of pageEquipmentCounts(page))rows.push([page,pageName(page),type.name,type.mark||'',count,countUnit(type)]);const csv='\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n');downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),`${safeFilename(state.project.name||'設備数量')}_ページ別設備数量.csv`);showToast('ページ別設備数量CSVを書き出しました')}

function submissionSettingsHtml(){
  const markers=[...(state.project?.markers||[])].sort((a,b)=>Number(a.page)-Number(b.page)||markerTag(a).localeCompare(markerTag(b),'ja',{numeric:true}));
  if(!markers.length)return '<div class="list-empty">図面上に設備を配置すると設定できます。</div>';
  return `<p class="master-intro">報告があるページだけを印刷します。図面上は整理番号を表示し、報告箇所に「！」、写真がある箇所に番号なしのカメラ印を付けます。写真番号は付けず、位置確認用として使う想定です。</p><label class="draw-only-reported"><input type="checkbox" data-draw-only-reported ${state.project?.submissionOptions?.onlyReported!==false?'checked':''}>報告を登録した設備だけを図面に表示</label><div class="draw-export-list">${markers.map(m=>{const t=getType(m.typeId),conf=m.submission||{};const findings=(m.findings||[]).map((f,index)=>({f,index})).filter(({f})=>f.severity!=='メモ'&&f.severity!=='参考写真');return `<section class="draw-export-item"><label class="draw-export-equipment"><input type="checkbox" data-draw-marker="${escapeHtml(m.id)}" ${conf.showMarker!==false?'checked':''}><span class="export-type-icon" style="--type-color:${escapeHtml(t.color||'#1769aa')}">${glyphHtml(t)}</span><strong>${escapeHtml(markerTag(m,t))}　${escapeHtml(t.name)}</strong><small>${escapeHtml(pageName(m.page))}${m.memo?` ・${escapeHtml(m.memo)}`:''}</small></label>${findings.length?findings.map(({f,index})=>{const defaultShow=f.submissionShow??!!(f.title||f.detail);const text=f.submissionText??(f.title||f.detail||'');return `<div class="draw-export-finding"><label><input type="checkbox" data-draw-finding="${escapeHtml(m.id)}:${index}" ${defaultShow?'checked':''}>報告を表示</label><input type="text" data-draw-text="${escapeHtml(m.id)}:${index}" value="${escapeHtml(text)}" placeholder="図面の下の報告一覧に載せる文言"></div>`}).join(''):'<div class="draw-export-finding muted">報告内容は未登録です</div>'}</section>`}).join('')}</div><p class="modal-hint">図面は元PDFのページ画像を使います。ブラウザーの印刷画面からPDF保存できます。</p>`
}
function openSubmissionSettings(){
  if(!state.pdf||!state.project?.pdfBlob){showToast('先に図面PDFを読み込んでください');return}
  showModal('指摘箇所確認図の設定',submissionSettingsHtml(),()=>{
    const form=$('#modalRoot');
    state.project.submissionOptions={...(state.project.submissionOptions||{}),onlyReported:form.querySelector('[data-draw-only-reported]')?.checked!==false};
    for(const m of state.project.markers){const box=form.querySelector(`[data-draw-marker="${CSS.escape(m.id)}"]`);m.submission=m.submission||{};m.submission.showMarker=box?box.checked:true;for(let i=0;i<(m.findings||[]).length;i++){const key=`${m.id}:${i}`,check=form.querySelector(`[data-draw-finding="${CSS.escape(key)}"]`),text=form.querySelector(`[data-draw-text="${CSS.escape(key)}"]`);if(check)m.findings[i].submissionShow=check.checked;if(text)m.findings[i].submissionText=text.value.trim()}}
    saveSoon();closeModal();openSubmissionDrawing();
  });
  $('#modalSave').textContent='図面を作成';
}
function drawingReportRecords(){
  const source=reportRecords(state.project),groups=groupReportRecords(source),groupNumbers=new Map();for(const g of groups)for(const r of g.entries)groupNumbers.set(r,g.number);
  const out=[];let photoRow=0;
  for(const r of source){const {m,t,f}=r;const photos=[];for(let n=0;n<(f.photos||[]).length;n++){photoRow++;photos.push(photoRow)}if(f.severity==='メモ'||f.severity==='参考写真'||f.submissionShow===false)continue;const text=(f.submissionText??r.title??r.detail??'').trim();if(!text)continue;out.push({number:groupNumbers.get(r)||(photos[0]||out.length+1),m,t,f,text,photos})}
  return out;
}
async function openSubmissionDrawing(){
  const win=window.open('','_blank');if(!win){showToast('新しいタブが開けません。ブラウザーのポップアップを許可してください');return}
  win.document.write('<!doctype html><meta charset="utf-8"><title>提出用図面を作成中</title><p style="font:16px sans-serif;padding:24px">PDFページを準備しています…</p>');
  try{
    const p=state.project,records=drawingReportRecords(),pages=[];
    if(!records.length){win.document.body.innerHTML='<p style="font:16px sans-serif;padding:24px">印刷対象の報告内容がありません。印刷する報告を選択してください。</p>';return}
    const pageNumbers=[...new Set(records.map(r=>Number(r.m.page)).filter(n=>n>0))].sort((a,b)=>a-b),onlyReported=p.submissionOptions?.onlyReported!==false;
    for(const pageNo of pageNumbers){
      const page=await state.pdf.getPage(pageNo),viewport=page.getViewport({scale:1.25}),canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;
      const reports=records.filter(r=>Number(r.m.page)===pageNo),reportedIds=new Set(reports.map(r=>r.m.id)),visible=p.markers.filter(m=>Number(m.page)===pageNo&&m.submission?.showMarker!==false&&(!onlyReported||reportedIds.has(m.id)));
      let overlay='';
      for(const m of visible){const t=getType(m.typeId),x=m.x*viewport.width,y=m.y*viewport.height,size=Math.max(24,Math.min(52,Number(m.size)||28)),fill=t.color||'#1769aa',markerReports=reports.filter(r=>r.m.id===m.id),hasPhoto=markerReports.some(r=>r.photos.length>0),glyph=t.iconData?`<image href="${escapeHtml(t.iconData)}" x="${x-size/2+3}" y="${y-size/2+3}" width="${size-6}" height="${size-6}" preserveAspectRatio="xMidYMid meet"/>`:`<text x="${x}" y="${y+5}" text-anchor="middle" font-size="${Math.min(19,size*.5)}" font-weight="800" fill="${escapeHtml(t.textColor||'#fff')}">${escapeHtml(t.glyph||t.name.slice(0,1))}</text>`;
        overlay+=`<g transform="translate(${x} ${y}) rotate(${Number(m.rotation)||0}) scale(${m.flipX?-1:1} ${m.flipY?-1:1}) translate(${-x} ${-y})"><rect x="${x-size/2}" y="${y-size/2}" width="${size}" height="${size}" rx="${Math.min(8,size/4)}" fill="${escapeHtml(fill)}" stroke="#fff" stroke-width="3"/>${glyph}</g><text x="${x}" y="${y+size/2+14}" text-anchor="middle" font-size="12" font-weight="700" fill="#172536" stroke="#fff" stroke-width="3" paint-order="stroke">${escapeHtml(markerTag(m,t))}</text>`;
        if(markerReports.length)overlay+=`<g><circle cx="${x-size/2+1}" cy="${y-size/2+1}" r="12" fill="#cf2634" stroke="#fff" stroke-width="3"/><text x="${x-size/2+1}" y="${y-size/2+7}" text-anchor="middle" font-size="17" font-weight="900" fill="#fff">!</text></g>`;
        if(hasPhoto){const cx=x+size/2-1,cy=y-size/2+1;overlay+=`<g><circle cx="${cx}" cy="${cy}" r="12" fill="#fff" stroke="#18334d" stroke-width="2.5"/><rect x="${cx-7}" y="${cy-4}" width="14" height="10" rx="2" fill="#18334d"/><path d="M ${cx-4} ${cy-4} l2 -3 h5 l2 3" fill="#18334d"/><circle cx="${cx}" cy="${cy+1}" r="2.7" fill="#fff"/></g>`}
      }
      const svg=`<svg class="overlay" viewBox="0 0 ${viewport.width} ${viewport.height}" xmlns="http://www.w3.org/2000/svg">${overlay}</svg>`,rows=reports.map(r=>`<div class="report-row"><b>報告${r.number}</b><span>${escapeHtml(markerTag(r.m,r.t))}　${escapeHtml(r.t.name)}</span><span>${escapeHtml(r.text)}</span><small>${r.photos.length?'写真あり':''}</small></div>`).join('');
      const ratio=viewport.width/viewport.height,drawWidth=Math.min(279,151*ratio),drawHeight=drawWidth/ratio;
      pages.push(`<section class="sheet"><h1>${escapeHtml(pageName(pageNo))} <small>${pageNo} / ${state.pdf.numPages}</small></h1><div class="drawing" style="width:${drawWidth}mm;height:${drawHeight}mm"><img src="${canvas.toDataURL('image/jpeg',.84)}" alt="${escapeHtml(pageName(pageNo))}">${svg}</div><div class="reports">${rows}</div></section>`);
    }
    const html=`<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(p.name||'指摘箇所確認図')}</title><style>*{box-sizing:border-box}body{margin:0;background:#e9edf1;color:#172536;font-family:-apple-system,BlinkMacSystemFont,"Yu Gothic","Meiryo",sans-serif}.toolbar{position:sticky;top:0;z-index:5;background:#14283d;color:#fff;padding:10px 16px;display:flex;align-items:center;justify-content:space-between;font-size:13px}.toolbar button{border:0;border-radius:7px;padding:9px 16px;background:#2d6fc4;color:#fff;font-weight:700;cursor:pointer}.sheet{width:297mm;min-height:210mm;margin:12px auto;padding:7mm 9mm;background:white;page-break-after:always;break-after:page;overflow:hidden}.sheet:last-child{page-break-after:auto;break-after:auto}.sheet h1{font-size:13pt;margin:0 0 3mm}.sheet h1 small{font-size:8pt;font-weight:400;color:#667}.drawing{position:relative;margin:0 auto;overflow:hidden}.drawing img,.overlay{position:absolute;inset:0;width:100%;height:100%;object-fit:fill}.reports{margin-top:3mm;font-size:8pt}.report-row{display:grid;grid-template-columns:18mm 52mm 1fr 24mm;gap:2mm;padding:1.2mm 1mm;border-bottom:1px solid #cbd3dc;align-items:start}.report-row b{color:#b22}.report-row small{font-size:7pt}.report-empty{color:#7c8792;padding:2mm}.hint{color:#d9e5f0;font-size:11px}@page{size:A4 landscape;margin:0}@media print{body{background:white}.toolbar{display:none}.sheet{margin:0;box-shadow:none;min-height:210mm}}@media screen{.sheet{box-shadow:0 2px 14px #0002}}</style></head><body><div class="toolbar"><span class="hint">指摘があるページだけを出力します。「！」は報告箇所、カメラ印は写真がある箇所です。</span><button onclick="window.print()">印刷 / PDF保存</button></div>${pages.join('')}</body></html>`;
    win.document.open();win.document.write(html);win.document.close();
  }catch(err){console.error(err);win.document.body.innerHTML='<p style="font:16px sans-serif;padding:24px">提出用図面を作成できませんでした。PDFとメモリの状態を確認してください。</p>';showToast('提出用図面を作成できませんでした')}
}
